
.ap-scope {
  width: 100%;
  max-width: 880px;
  margin: 0 auto;
  font-family: var(--font-ui);
  user-select: none;
  font-weight: 400;
  color: var(--c-text);
}

/* ══ 整机外框：白卡浮在稍深白基底上 ══ */
.ap-shell {
  display: flex;
  flex-direction: column;
  width: 100%;
  aspect-ratio: 4 / 3;
  min-height: 430px;
  background: var(--c-panel);
  border: 1px solid var(--c-border);
  border-radius: 24px;
  box-shadow: var(--lift-hi);
  overflow: hidden;
}

/* ── 顶部栏 ── */
.ap-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-shrink: 0;
  height: 52px;
  padding: 0 16px;
  background: #fafbfc;
  border-bottom: 1px solid var(--c-divider);
}

.ap-top__left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.ap-dots {
  display: flex;
  align-items: center;
  gap: 5px;
}

.ap-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #dcdde1;
}

.ap-dot:first-child {
  background: #e3e4e8;
}

.ap-top__name {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--c-text);
  white-space: nowrap;
}

.ap-top__pill {
  font-size: 10.5px;
  font-weight: 500;
  padding: 2.5px 9px;
  border-radius: 999px;
  background: var(--c-primary-dim);
  color: var(--c-primary);
  white-space: nowrap;
}

.ap-top__right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.ap-top__clock {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  color: var(--c-text-faint);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* ── 侧栏开关：参考图右上角「≡ 侧栏 / ≡ 展开」 ── */
.ap-toggle {
  display: flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 11px 0 9px;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  background: #ffffff;
  color: var(--c-text-muted);
  font-family: var(--font-ui);
  font-size: 11.5px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.25s var(--ease),
    color 0.25s var(--ease),
    box-shadow 0.25s var(--ease);
  -webkit-tap-highlight-color: transparent;
}

.ap-toggle:hover {
  background: #f5f6f8;
  color: var(--c-text);
}

.ap-toggle--on {
  background: var(--c-primary-dim);
  border-color: #d6e6ff;
  color: var(--c-primary);
}

.ap-toggle__ico {
  width: 13px;
  height: 13px;
  stroke: currentColor;
  stroke-width: 2;
  fill: none;
  stroke-linecap: round;
}

.ap-circle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--c-border);
  border-radius: 50%;
  background: #ffffff;
  color: var(--c-text-faint);
  cursor: pointer;
  transition:
    background 0.25s var(--ease),
    color 0.25s var(--ease);
  -webkit-tap-highlight-color: transparent;

  svg {
    width: 13px;
    height: 13px;
    stroke: currentColor;
    stroke-width: 1.8;
    fill: none;
  }

  &:hover {
    background: #f5f6f8;
    color: var(--c-text);
  }
}

/* ── 主体分栏 ── */
.ap-split {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

/* 左侧视图控制 */
.ap-sidebar {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  width: 168px;
  padding: 14px 10px;
  background: #f7f8fa;
  border-right: 1px solid var(--c-divider);
  overflow: hidden;
  transition: width 0.4s var(--ease);
}

.ap-sidebar--rail {
  width: 62px;
  padding: 14px 7px;
}

.ap-sidebar__title {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--c-text-faint);
  padding: 0 8px 10px;
  white-space: nowrap;
  opacity: 1;
  transition:
    opacity 0.22s var(--ease),
    padding 0.3s var(--ease);

  .ap-sidebar--rail & {
    opacity: 0;
    padding-bottom: 4px;
    pointer-events: none;
  }
}

.ap-nav {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.ap-nav__item {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 10px;
  border: none;
  border-radius: 12px;
  background: transparent;
  color: var(--c-text-muted);
  font-family: var(--font-ui);
  font-size: 12.5px;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  transition:
    background 0.25s var(--ease),
    color 0.25s var(--ease),
    box-shadow 0.25s var(--ease),
    padding 0.4s var(--ease);

  &:hover {
    background: rgba(0, 0, 0, 0.035);
    color: var(--c-text);
  }

  .ap-sidebar--rail & {
    justify-content: center;
    gap: 0;
    padding: 9px 0;
  }
}

.ap-nav__ico {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  stroke: currentColor;
  stroke-width: 1.6;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.ap-nav__label {
  overflow: hidden;
  max-width: 100px;
  opacity: 1;
  transition:
    opacity 0.2s var(--ease),
    max-width 0.35s var(--ease);

  .ap-sidebar--rail & {
    max-width: 0;
    opacity: 0;
  }
}

.ap-nav__item--on {
  background: #ffffff;
  color: var(--c-primary);
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

.ap-sidebar__foot {
  margin-top: auto;
  padding-top: 10px;
}

.ap-font {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3px;

  .ap-sidebar--rail & {
    grid-template-columns: 1fr;
  }
}

.ap-font__btn {
  padding: 5px 0;
  border: none;
  border-radius: 7px;
  background: #eceef2;
  color: var(--c-text-faint);
  font-family: var(--font-ui);
  font-size: 10px;
  font-weight: 500;
  cursor: pointer;
  transition:
    background 0.2s ease,
    color 0.2s ease;
  -webkit-tap-highlight-color: transparent;

  &:hover {
    background: #e3e5ea;
    color: var(--c-text);
  }
}

.ap-font__btn--on {
  background: var(--c-text);
  color: #ffffff;
  font-weight: 600;
}

/* ── 右侧内容 ── */
.ap-content {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  background: var(--c-panel);
}

.ap-content__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-shrink: 0;
  padding: 16px 20px 12px;
}

.ap-content__lead {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ap-content__title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--c-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ap-content__sub {
  font-size: 11px;
  font-weight: 400;
  color: var(--c-text-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  &:empty {
    display: none;
  }
}

.ap-tier {
  font-size: 10.5px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--c-primary-dim);
  color: var(--c-primary);
  white-space: nowrap;
}

.ap-content__body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 20px 16px;
  scrollbar-width: thin;
  scrollbar-color: #d1d3d8 transparent;

  &::-webkit-scrollbar {
    width: 5px;
  }

  &::-webkit-scrollbar-thumb {
    background: #d1d3d8;
    border-radius: 3px;
  }
}

/* ── 底部 ── */
.ap-foot {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  flex-shrink: 0;
  padding: 10px 18px;
  background: #fafbfc;
  border-top: 1px solid var(--c-divider);
}

.ap-foot__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ap-foot__dot--ok {
  background: var(--c-ok);
  box-shadow: 0 0 6px rgba(52, 199, 89, 0.55);
}

.ap-foot__dot--warn {
  background: var(--c-warning);
  box-shadow: 0 0 6px rgba(255, 149, 0, 0.5);
}

.ap-foot__dot--bad {
  background: var(--c-danger);
  box-shadow: 0 0 6px rgba(255, 59, 48, 0.5);
}

.ap-foot__text {
  font-size: 11px;
  font-weight: 400;
  color: var(--c-text-faint);
  line-height: 1.5;
  text-align: center;
}

@media (max-width: 640px) {
  .ap-shell {
    aspect-ratio: auto;
    min-height: 460px;
  }

  .ap-top__pill,
  .ap-top__clock {
    display: none;
  }

  .ap-sidebar {
    width: 132px;
  }

  .ap-sidebar--rail {
    width: 52px;
  }

  .ap-content__head {
    padding: 14px 14px 10px;
  }

  .ap-content__body {
    padding: 0 14px 14px;
  }
}
