
.wrap {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-bottom: 4px;
}

/* ── 身份四格 + 当前位置 ── */
.bento {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.cell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 34px;
  padding: 8px 12px;
  border-radius: 12px;
  background: var(--c-sunken);
}

.cell--wide {
  grid-column: 1 / -1;
  align-items: flex-start;

  .cell__k {
    padding-top: 1px;
  }

  .cell__v {
    white-space: normal;
    line-height: 1.5;
    text-align: right;
  }
}

.cell__k {
  font-size: 12px;
  font-weight: 400;
  color: var(--c-text-faint);
  white-space: nowrap;
  flex-shrink: 0;
}

.cell__v {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell__v--num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* ── 人气 / 实力：双圆环并排 ── */
.rings {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.ring-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 13px 12px 12px;
  border-radius: 14px;
  background: var(--c-card);
  border: 1px solid var(--c-divider);
  min-width: 0;
}

.ring-card__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  width: 100%;
}

.ring-card__k {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--c-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ring-card__badge {
  font-size: 9.5px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 999px;
  background: #eefaf2;
  color: var(--c-success);
  white-space: nowrap;
  flex-shrink: 0;
}

.ring-card__badge--blue {
  background: var(--c-primary-dim);
  color: var(--c-primary);
}

.ring-card__foot {
  font-size: 11px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--c-text-faint);
  text-align: center;
}

/* ── 卡片 ── */
.card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 14px 15px;
  border-radius: 14px;
  background: var(--c-card);
  border: 1px solid var(--c-divider);
}

.card--plain {
  gap: 9px;
}

.card__tag {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.card__title {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: var(--c-text);
  margin-top: 3px;
  line-height: 1.2;
}

.card__sub {
  font-size: 11.5px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--c-text-muted);
}

/* ── 资源：左四环 + 右清单 ── */
.res {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  margin-top: 12px;
}

.res__rings {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  flex-shrink: 0;
}

.res__ring {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  width: 58px;
}

.res__ring-k {
  font-size: 10px;
  font-weight: 500;
  color: var(--c-text-muted);
  white-space: nowrap;
  text-align: center;
}

.res__ring-v {
  font-size: 9px;
  font-weight: 500;
  color: var(--c-text-faint);
  white-space: nowrap;
}

.res__list {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0;
  flex: 1;
  min-width: 0;
  padding-top: 2px;
}

.res__row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 5px 0;
  border-bottom: 1px solid var(--c-divider);

  &:last-child {
    border-bottom: none;
  }
}

.res__row-k {
  font-size: 10.5px;
  font-weight: 400;
  color: var(--c-text-faint);
  white-space: nowrap;
  flex-shrink: 0;
  width: 52px;
}

.res__row-v {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--c-text);
  line-height: 1.45;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.res__row-v--empty {
  color: var(--c-text-faint);
  font-weight: 400;
}

@media (max-width: 560px) {
  .res {
    flex-direction: column;
    gap: 10px;
  }

  .res__rings {
    width: 100%;
    justify-content: space-between;
  }

  .res__row-k {
    width: auto;
  }
}

/* ── 属性 ── */
.attrs {
  display: flex;
  flex-direction: column;
}

.attrs__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 7px 0;
  border-bottom: 1px solid var(--c-divider);

  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  &:first-child {
    padding-top: 2px;
  }
}

.attrs__k {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--c-text-faint);
  white-space: nowrap;
}

.attrs__v {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  text-align: right;
}

/* ── 文本卡 ── */
.bio {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 12px 14px;
  border-radius: 14px;
  background: var(--c-sunken);
}

.bio__row {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.bio__k {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-faint);
}

.bio__v {
  margin: 0;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.62;
  color: var(--c-text-body);
}
