
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── 积蓄卡 ── */
.rank {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: var(--c-bar);
}

.rank__tag {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.rank__hero {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}

.rank__n {
  font-family: var(--font-mono);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.04em;
  line-height: 1.15;
  font-variant-numeric: tabular-nums;
}

.rank__n--ok {
  color: var(--c-text);
}

.rank__n--warn {
  color: var(--c-warning);
}

.rank__n--bad {
  color: var(--c-danger);
}

.rank__u {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--c-text-faint);
  font-variant-numeric: tabular-nums;
}

.rank__hint {
  font-size: 11.5px;
  color: var(--c-text-muted);
  line-height: 1.55;
}

/* ── Bento ── */
.bento {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.cell {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--c-sunken);
  min-width: 0;
}

.cell__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.cell__k {
  font-size: 12px;
  color: var(--c-text-faint);
}

.cell__cycle {
  font-size: 10px;
  color: var(--c-text-faint);
}

.cell__v {
  font-family: var(--font-mono);
  font-size: 14.5px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell__cny {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--c-text-faint);
  font-variant-numeric: tabular-nums;
}

.cell__note {
  font-size: 10.5px;
  color: var(--c-text-muted);
  line-height: 1.45;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── 月净流 ── */
.flow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 12px;
  border-radius: 12px;
  background: var(--c-sunken);
}

.flow__k {
  font-size: 11.5px;
  color: var(--c-text-faint);
}

.flow__v {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.flow__v--ok {
  color: var(--c-success);
}

.flow__v--warn {
  color: var(--c-warning);
}

.flow__v--bad {
  color: var(--c-danger);
}

/* ── 卡片与文字 ── */
.card {
  padding: 12px 14px;
  border-radius: 14px;
  background: var(--c-sunken);
}

.card__h {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-faint);
  margin-bottom: 4px;
}

.card__p {
  font-size: 12px;
  line-height: 1.55;
  color: #3a3a3c;
  white-space: pre-wrap;
}

.guard {
  padding-top: 10px;
  border-top: 1px solid #efefef;
  font-size: 11px;
  color: var(--c-text-faint);
  line-height: 1.6;
}
