
.g {
  position: relative;
  width: var(--g-size);
  height: var(--g-size);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.g__svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.g__track {
  stroke: #e8e8e8;
}

.g__arc {
  transition:
    stroke-dasharray 0.6s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)),
    stroke 0.3s ease;
}

.g__num {
  position: relative;
  font-family: var(--font-ui);
  font-size: calc(var(--g-size) * 0.26);
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--c-text);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
