
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── 一位卡 ── */
.rank {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: var(--c-bar);
}

.rank__tag {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.rank__hero {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.rank__n {
  font-family: var(--font-mono);
  font-size: 42px;
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.rank__u {
  font-size: 12px;
  font-weight: 500;
  color: var(--c-text-muted);
}

.track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-border);
  overflow: hidden;
}

.track__fill {
  height: 100%;
  border-radius: 3px;
  background: var(--c-text);
  transition: width 0.5s var(--ease);
}

/* ── Bento 方格 ── */
.bento {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.cell {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 12px;
  background: var(--c-sunken);
}

.cell__k {
  font-size: 12px;
  color: var(--c-text-faint);
  flex-shrink: 0;
}

.cell__v {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  text-align: right;
  line-height: 1.4;
}

.cell__v--num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.hint {
  padding: 30px 0;
  text-align: center;
  font-size: 12px;
  color: var(--c-text-faint);
}

/* ── 既往成就（可折叠） ── */
.ach {
  border: 1px solid var(--c-border);
  border-radius: 14px;
  background: var(--c-card);
  overflow: hidden;
}

.ach__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
  padding: 12px 14px;
  border: none;
  background: transparent;
  font-family: var(--font-ui);
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.2s var(--ease);

  &:hover {
    background: rgba(0, 0, 0, 0.025);
  }
}

.ach__head-l {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.ach__tag {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--c-text);
  white-space: nowrap;
}

.ach__count {
  font-size: 10px;
  font-weight: 500;
  padding: 1.5px 7px;
  border-radius: 999px;
  background: var(--c-sunken);
  color: var(--c-text-faint);
  white-space: nowrap;
}

.ach__chev {
  width: 15px;
  height: 15px;
  flex-shrink: 0;
  fill: none;
  stroke: var(--c-text-faint);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: transform 0.3s var(--ease);
}

.ach__chev--open {
  transform: rotate(180deg);
}

.ach__body {
  padding: 0 14px 10px;
}

.ach__list {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin: 0;
  padding: 0;
  list-style: none;
}

.ach__item {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 7px 0;
  border-top: 1px solid var(--c-divider);
}

.ach__date {
  flex-shrink: 0;
  width: 72px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 500;
  color: var(--c-text-faint);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.ach__text {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.55;
  color: var(--c-text-body);
  min-width: 0;
}

.ach__empty {
  padding: 12px 0 4px;
  font-size: 11.5px;
  color: var(--c-text-faint);
  border-top: 1px solid var(--c-divider);
}

.ach-slide-enter-active,
.ach-slide-leave-active {
  transition:
    opacity 0.25s var(--ease),
    max-height 0.3s var(--ease);
  overflow: hidden;
  max-height: 640px;
}

.ach-slide-enter-from,
.ach-slide-leave-to {
  opacity: 0;
  max-height: 0;
}
