
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.card {
  padding: 14px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: #ffffff;
}

.card__h {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
  margin-bottom: 10px;
}

.empty {
  font-size: 12px;
  color: var(--c-text-faint);
  line-height: 1.65;
}

/* ── 恋爱线 ── */
.lines {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.line {
  padding: 12px;
  border-radius: 14px;
  background: var(--c-sunken);
}

.line__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.line__name {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--c-text);
}

.line__stage {
  font-size: 10px;
  font-weight: 600;
  padding: 2.5px 9px;
  border-radius: 999px;
  background: #ffffff;
  white-space: nowrap;
}

.line__stage--cool {
  color: var(--c-text-muted);
}

.line__stage--warm {
  color: var(--c-warning);
}

.line__stage--hot {
  color: var(--c-primary);
  background: var(--c-primary-dim);
}

.mini {
  display: grid;
  grid-template-columns: 28px 1fr 26px;
  gap: 10px;
  align-items: center;

  & + & {
    margin-top: 6px;
  }
}

.mini__k {
  font-size: 10.5px;
  color: var(--c-text-faint);
}

.mini__track {
  height: 4px;
  background: #ffffff;
}

.mini__v {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-muted);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.mini__v--hot {
  color: var(--c-danger);
}

.warn {
  margin-top: 9px;
  font-size: 11px;
  font-weight: 500;
  color: var(--c-danger);
}

/* ── 关系网 ── */
.rel {
  display: flex;
  flex-direction: column;
}

.rel__row {
  display: grid;
  grid-template-columns: 1fr auto 56px 22px;
  gap: 10px;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid #efefef;

  &:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  &:first-child {
    padding-top: 0;
  }
}

.rel__name {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tag {
  font-size: 10px;
  font-weight: 600;
  padding: 1.5px 8px;
  border-radius: 999px;
  background: var(--c-sunken);
  white-space: nowrap;
}

.tag--ok {
  color: var(--c-success);
}

.tag--mid {
  color: var(--c-text-muted);
}

.tag--bad {
  color: var(--c-danger);
}

.rel__track {
  height: 4px;
}

.rel__v {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-faint);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

/* ── 通用条 ── */
.track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-border);
  overflow: hidden;
}

.track__fill {
  height: 100%;
  border-radius: 3px;
  background: var(--c-text);
  transition: width 0.5s var(--ease);
}

.track__fill--light {
  background: var(--c-text-faint);
}

.track__fill--warn {
  background: var(--c-warning);
}

.track__fill--danger {
  background: var(--c-danger);
}
