
.wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── 状态 ── */
.state {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 14px;
  border-radius: 12px;
  background: var(--c-sunken);
}

.state__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.state__dot--ok {
  background: var(--c-ok);
  box-shadow: 0 0 7px rgba(52, 199, 89, 0.5);
}

.state__dot--mid {
  background: #c7c7cc;
}

.state__dot--warn {
  background: var(--c-warning);
  box-shadow: 0 0 7px rgba(249, 115, 22, 0.45);
}

.state__dot--bad {
  background: var(--c-danger);
  box-shadow: 0 0 7px rgba(225, 29, 72, 0.45);
}

.state__label {
  font-size: 13.5px;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--c-text);
}

.state__sub {
  font-size: 11.5px;
  color: var(--c-text-muted);
  line-height: 1.45;
}

/* ── 体重卡 ── */
.rank {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: var(--c-bar);
}

.rank__tag {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--c-text-faint);
}

.rank__hero {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.rank__n {
  font-family: var(--font-mono);
  font-size: 42px;
  font-weight: 700;
  letter-spacing: -0.05em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.rank__u {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--c-text-faint);
}

.tri {
  font-size: 13px;
  line-height: 1;
  transform: translateY(-4px);
}

.tri--up {
  color: var(--c-danger);
}

.tri--down {
  color: var(--c-success);
}

.rank__hint {
  font-size: 11.5px;
  color: var(--c-text-muted);
  line-height: 1.55;
}

.daily {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 4px;
  padding-top: 9px;
  border-top: 1px solid #efefef;
  font-size: 11px;
  line-height: 1.55;
}

.daily__k {
  color: var(--c-text-faint);
}

.daily__v {
  font-family: var(--font-mono);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.daily__v--calm {
  color: var(--c-text-muted);
}

.daily__v--warm {
  color: var(--c-warning);
}

.daily__v--hot {
  color: var(--c-danger);
}

.daily__kg {
  color: var(--c-text-faint);
}

.daily__loop {
  color: var(--c-warning);
  font-weight: 600;
}

/* ── 疲劳 ── */
.fatigue {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px;
  border: 1px solid var(--c-border);
  border-radius: 16px;
  background: #ffffff;
}

.fatigue__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.fatigue__k {
  font-size: 11.5px;
  color: var(--c-text-faint);
}

.fatigue__v {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--c-text);
}

.fatigue__v--hot {
  color: var(--c-danger);
}

.fatigue__u {
  margin-left: 2px;
  font-size: 11px;
  font-weight: 500;
  color: var(--c-text-faint);
}

.fatigue__hint {
  font-size: 11px;
  color: var(--c-text-faint);
  line-height: 1.55;
}

/* ── 伤病卡 ── */
.card {
  padding: 12px 14px;
  border-radius: 14px;
  background: var(--c-sunken);
}

.card__h {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--c-text-faint);
  margin-bottom: 4px;
}

.card__p {
  font-size: 12px;
  line-height: 1.55;
  color: #3a3a3c;
  white-space: pre-wrap;
}

/* ── 通用条 ── */
.track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-border);
  overflow: hidden;
}

.track__fill {
  height: 100%;
  border-radius: 3px;
  background: var(--c-text);
  transition: width 0.5s var(--ease);
}

.track__fill--warn {
  background: var(--c-warning);
}

.track__fill--danger {
  background: var(--c-danger);
}
